INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Überwachung der Fortschritte Teil des Controllings?', 2, '[{"text": "Ja", "correct": true, "because": "Überprüft Projektverlauf"}, {"text": "Nein", "correct": false, "because": "Es gehört zum Controlling"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel hat die Überwachung der Fortschritte?', 3, '[{"text": "Sicherstellung des Projektfortschritts", "correct": true, "because": "Kontrolliert Zeitplan"}, {"text": "Team direkt einteilen", "correct": false, "because": "Durchführungsaspekt"}, {"text": "Kosten neu kalkulieren", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Fortschrittsüberwachung vergleicht Ist- und Soll-Zustand. b) Sie erfolgt nur am Projektstart.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, fortlaufend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente werden bei der Fortschrittsüberwachung betrachtet?', 4, '[{"text": "Meilensteine", "correct": true, "because": "Markieren Fortschritt"}, {"text": "Unklare Berichte", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Zeitplan", "correct": true, "because": "Vergleichsbasis"}, {"text": "Arbeitspakete", "correct": true, "because": "Zeigen Aufgabenstatus"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Controlling ohne Fortschrittsüberwachung effektiv sein?', 2, '[{"text": "Nein", "correct": true, "because": "Fortschritt ist Kern"}, {"text": "Ja", "correct": false, "because": "Unvollständig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug hilft bei der Fortschrittsüberwachung?', 3, '[{"text": "Statusberichte", "correct": true, "because": "Zeigen aktuellen Stand"}, {"text": "Keine Dokumentation", "correct": false, "because": "Fehlt Nachweis"}, {"text": "Zufällige Notizen", "correct": false, "because": "Unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Fortschrittsüberwachung nur für große Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte brauchen sie"}, {"text": "Ja", "correct": false, "because": "Universelle Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode unterstützt die Fortschrittsüberwachung?', 3, '[{"text": "Earned Value Management", "correct": true, "because": "Misst Fortschritt"}, {"text": "Keine Analyse", "correct": false, "because": "Fehlt Kontrolle"}, {"text": "Spontane Überprüfung", "correct": false, "because": "Unsystematisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Fortschrittsüberwachung erkennt Verzögerungen. b) Sie ist nur für Kosten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, umfassender"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Fortschrittsüberwachung?', 3, '[{"text": "Verzögerungen bleiben unbemerkt", "correct": true, "because": "Keine Kontrolle"}, {"text": "Projekt wird schneller", "correct": false, "because": "Eher Verzögerung"}, {"text": "Kosten sinken", "correct": false, "because": "Können steigen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Fortschrittsüberwachung ohne Zeitplan erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Vergleichsbasis fehlt"}, {"text": "Ja", "correct": false, "because": "Unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt Fortschrittsüberwachung?', 3, '[{"text": "Meilenstein 1 fristgerecht prüfen", "correct": true, "because": "Konkret und real"}, {"text": "Irgendwas überprüfen", "correct": false, "because": "Zu vage"}, {"text": "Team soll schneller sein", "correct": false, "because": "Keine Überwachung"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Fortschrittsüberwachung nur für den Projektleiter relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Team braucht Rückmeldung"}, {"text": "Ja", "correct": false, "because": "Projektweite Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Daten werden bei der Fortschrittsüberwachung genutzt?', 4, '[{"text": "Statusmeldungen", "correct": true, "because": "Zeigen Ist-Zustand"}, {"text": "Unklare Schätzungen", "correct": false, "because": "Erschweren Kontrolle"}, {"text": "Arbeitsfortschritt", "correct": true, "because": "Misst Leistung"}, {"text": "Meilensteinberichte", "correct": true, "because": "Markieren Fortschritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Fortschrittsüberwachung regelmäßig erfolgen?', 2, '[{"text": "Ja", "correct": true, "because": "Fortlaufende Kontrolle nötig"}, {"text": "Nein", "correct": false, "because": "Einmalig unzureichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Fortschrittsüberwachung?', 3, '[{"text": "Abweichungen früh erkennen", "correct": true, "because": "Sichert Zeitplan"}, {"text": "Neue Ziele setzen", "correct": false, "because": "Initiierungsschritt"}, {"text": "Team neu einteilen", "correct": false, "because": "Durchführungsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Fortschrittsüberwachung ohne PSP erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Struktur fehlt"}, {"text": "Ja", "correct": false, "because": "Unstrukturiert unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert die Fortschrittsüberwachung?', 3, '[{"text": "Fehlende Berichte", "correct": true, "because": "Verhindern Analyse"}, {"text": "Klarer Zeitplan", "correct": false, "because": "Fördert Überwachung"}, {"text": "Gute Daten", "correct": false, "because": "Unterstützt Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Fortschrittsüberwachung steuert Anpassungen. b) Sie ist nur für technische Projekte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, breit anwendbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen der Fortschrittsüberwachung?', 3, '[{"text": "Pünktlichkeit gewährleisten", "correct": true, "because": "Kontrolliert Ablauf"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Steuerung", "correct": false, "because": "Fördert Anpassung"}]');
